CREATE COLUMN TABLE "TEST_AP"."@TASKLISTTEMPLATE" ("Code" NVARCHAR(50) NOT NULL , "Name" NVARCHAR(100) NOT NULL , "U_AttachFiles" NCLOB MEMORY THRESHOLD 1000, "U_Notes" NVARCHAR(150), PRIMARY KEY ("Code")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "KTASKLISTTEMPLATE_NAME" ON "TEST_AP"."@TASKLISTTEMPLATE" ( "Name" ASC )